<template>
  <div>
    <Hero :title=heroTitle :subtitle="splashText" :heroType=heroType />
    <div class="container">
      <Progress
      :max="store.state.splash.requests.length * 100"
      :value="reduceRequests().getProgress() > 0 ? reduceRequests().getProgress() : undefined"
      :className="[reduceRequests().getProgress() > 0 ? 'is-info' : '']" />
    </div>
  </div>
</template>

<script lang="ts" setup>
import * as Sentry from "@sentry/vue";
import * as TelemetryUtils from "@/overwolf/utils/telemetry";
import {Hero, Progress} from "@/r2modmanPlus/src/components/all";
import RequestItem from "@/r2modmanPlus/src/model/requests/RequestItem";
import LoggerProvider, {LogSeverity} from "@/r2modmanPlus/src/providers/ror2/logging/LoggerProvider";
import {computed, onMounted, ref} from "vue";
import {getStore} from "@/r2modmanPlus/src/providers/generic/store/StoreProvider";
import {State} from "@/r2modmanPlus/src/store";
import {useRouter} from "vue-router";
import {useSplashComposable} from "@/r2modmanPlus/src/components/composables/SplashComposable";

const store = getStore<State>();
let router = useRouter();

store.commit('splash/initialiseRequests');

const { reduceRequests } = useSplashComposable();

const heroTitle = ref<string>('Warming up');
const heroType = ref<string>('primary');
const splashText = computed(() => store.state.splash.splashText);

// Override the functionality from SplashMixin to allow OpenTelemetry injection.
async function getThunderstoreMods() {
  const tracer = TelemetryUtils.getPackageListUpdateTracer();

  await tracer.startActiveSpan("package-list-update", async (span) => {
    TelemetryUtils.setPackageListUpdateSpanAttributes(
      span,
      import.meta.url,
      "getThunderstoreMods",
      store.state.activeGame.internalFolderName
    );

    try {
      await store.dispatch("splash/getThunderstoreMods");
      TelemetryUtils.recordSuccess(span);
    } catch (e) {
      TelemetryUtils.recordError(span, e);
      Sentry.captureException(e);
    } finally {
      span.end();
    }
  });
}

onMounted(async () => {

  // No functional check for updates - Just progresses base "UpdateCheck" RequestItem.
  await store.dispatch('splash/setSplashText', 'Preparing to retrieve mods');
  const updateCheck: RequestItem = await store.dispatch('splash/getRequestItem', 'UpdateCheck');
  updateCheck.setProgress(100);

  const loader = async () => {
    try {
      getThunderstoreMods()
          .finally(() => router.push({name: 'profiles'}))
    } catch (err) {
      if (err instanceof Error) {
        LoggerProvider.instance.Log(LogSeverity.ERROR, `${err.name}: ${err.message}\n${err.stack}`);
      } else {
        console.error(err);
      }
    }
  }

  setTimeout(loader, 100);
});

</script>
